import{_ as t,o,c as d,a2 as s}from"./chunks/framework.BuA5Emwa.js";const k=JSON.parse('{"title":"sdd prompts and reply kinds","description":"How every sdd prompt is built, which reply kinds each prompt offers, and how long the old reply shapes are still read.","frontmatter":{"title":"sdd prompts and reply kinds","description":"How every sdd prompt is built, which reply kinds each prompt offers, and how long the old reply shapes are still read.","head":[["meta",{"property":"og:title","content":"sdd prompts and reply kinds · sdd"}],["meta",{"property":"og:description","content":"How every sdd prompt is built, which reply kinds each prompt offers, and how long the old reply shapes are still read."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/maintainers/prompts/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"sdd prompts and reply kinds · sdd"}],["meta",{"name":"twitter:description","content":"How every sdd prompt is built, which reply kinds each prompt offers, and how long the old reply shapes are still read."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/maintainers/prompts/"}]]},"headers":[],"relativePath":"maintainers/prompts.md","filePath":"maintainers/prompts.md","lastUpdated":1795162002000}'),a={name:"maintainers/prompts.md"};function i(n,e,r,h,l,c){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="prompts-and-reply-kinds" tabindex="-1">Prompts and reply kinds <a class="header-anchor" href="#prompts-and-reply-kinds" aria-label="Permalink to &quot;Prompts and reply kinds&quot;">​</a></h1><p>Every prompt that goes to a model, and whose reply sdd reads, follows one standard. This page is for people who change those prompts or their replies.</p><h2 id="one-prompt-standard" tabindex="-1">One prompt standard <a class="header-anchor" href="#one-prompt-standard" aria-label="Permalink to &quot;One prompt standard&quot;">​</a></h2><p><code>buildPrompt</code> in <code>packages/core/src/prompt.ts</code> makes every shipped prompt, with these sections in this order:</p><ol><li><strong>Role</strong>: who the model is, its job, its playbook.</li><li><strong>Scope</strong>: what the role owns, reads, may never do, and when it asks the person.</li><li><strong>Task</strong>: what to do now, numbered, with a &quot;Done when&quot; line.</li><li><strong>Inputs</strong>: every file, answer and tool result. Each is a fenced block marked untrusted data.</li><li><strong>Guardrails</strong>: shared rules, then the rules of that prompt.</li><li><strong>Style</strong>: plain English, one reply object.</li><li><strong>Output contract</strong>: the reply format, last, next to where the model writes. It is generated from the zod schema the parser reads with, with valid examples and one invalid example.</li></ol><p>The wording of each prompt is in <code>role/prompts.ts</code> (and <code>team/brain.ts</code> for the loop). Snapshots in <code>packages/core/src/__tests__/__snapshots__/prompts/</code> pin the full text.</p><h2 id="reply-kinds" tabindex="-1">Reply kinds <a class="header-anchor" href="#reply-kinds" aria-label="Permalink to &quot;Reply kinds&quot;">​</a></h2><p>Every reply is one JSON object with a <code>kind</code>. Each prompt offers a closed list of kinds, and a reply whose kind is not on the list gets one repair try. The schemas are in <code>reply-schemas.ts</code> and <code>team/loop-contract.ts</code>. The reader is <code>readKinded</code> in <code>reply-kind.ts</code>.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Offered by</th><th>Shape</th><th>Meaning</th></tr></thead><tbody><tr><td><code>draft</code></td><td>author, hand-off receiver, network owner, guide</td><td><code>{kind, text, action?}</code>; the guide also sends <code>parts?</code></td><td>The model&#39;s answer, and at most one <code>write_file</code> action for a person to approve</td></tr><tr><td><code>question</code></td><td>author in a guided run, network owner at a <code>boundary: ask</code> node, guide</td><td><code>{kind, text}</code></td><td>One question for the person. The run waits for the answer. Any parts or action sent with it are ignored</td></tr><tr><td><code>critique</code></td><td>critic</td><td><code>{kind, text, gaps?}</code></td><td>A verdict and the gaps found. Each gap cites a check id</td></tr><tr><td><code>revision</code></td><td>author, in a revision</td><td><code>{kind, text, changed, open?, action?}</code></td><td>The full revised draft, the cites fixed, and the cites left open</td></tr><tr><td><code>post</code></td><td>room</td><td><code>{kind, text, cite?}</code></td><td>A note or an answer</td></tr><tr><td><code>objection</code></td><td>room</td><td><code>{kind, text, cite}</code></td><td>The draft breaks a check or a rule. A cite is required</td></tr><tr><td><code>agree</code></td><td>room</td><td><code>{kind, text, cite?}</code></td><td>The draft is accepted. When the stage has verify commands, the cite is the evidence path for this commit</td></tr><tr><td><code>block</code></td><td>room</td><td><code>{kind, text, cite?}</code></td><td>The model cannot go on until the person decides</td></tr><tr><td><code>plan</code></td><td>loop</td><td><code>{kind, items}</code></td><td>The steps the bot will take</td></tr><tr><td><code>tool</code></td><td>loop</td><td><code>{kind, name, args?}</code></td><td>One tool call. The result comes back on the next turn</td></tr><tr><td><code>check</code></td><td>loop</td><td><code>{kind, claim, evidence?}</code></td><td>A claim about the work. A claim that something passes needs evidence</td></tr><tr><td><code>ask</code></td><td>loop</td><td><code>{kind, question, options, suggest?}</code></td><td>Stop and ask the person one question</td></tr><tr><td><code>done</code></td><td>loop</td><td><code>{kind, summary, outputs, evidence?}</code></td><td>Finish the work</td></tr><tr><td><code>plan_tree</code></td><td>lead</td><td><code>{kind, text, plan}</code></td><td>A plan of services, owners and decisions, at most two levels deep</td></tr></tbody></table><p>Rules that hold for every kind:</p><ul><li>The model never sends a room <code>decision</code>. Only a person records one. A reply that names it is repaired.</li><li>A prompt offers only its own kinds. The kind <code>question</code> is offered only where the run can wait for an answer. At a <code>boundary: stop</code> node a <code>question</code> is read as the node&#39;s result.</li><li>A key a schema does not list is dropped, not refused. A loop step is stricter: an unknown key in a step makes it not valid, as before.</li><li>Inside the run, a question is stored as <code>text</code> with one <code>Question:</code> prefix, whichever form arrived. Nothing downstream of the reader changed.</li><li>Two loop kinds, <code>understand</code> and <code>reflect</code>, are read as steps that do almost nothing. No prompt offers them, so they are not kinds a model should send.</li></ul><h2 id="old-shapes-are-still-read" tabindex="-1">Old shapes are still read <a class="header-anchor" href="#old-shapes-are-still-read" aria-label="Permalink to &quot;Old shapes are still read&quot;">​</a></h2><p>Before <code>kind</code>, each reply had its own shape. Those shapes are still read, for one minor release, so a model, a script or an <code>SDD_ROLE_MODEL</code> adapter written for the old prompts keeps working.</p><table tabindex="0"><thead><tr><th>Old shape</th><th>Read as</th><th><code>shape</code> in the log</th></tr></thead><tbody><tr><td><code>{text, action?}</code> with no <code>kind</code></td><td><code>draft</code></td><td><code>no_kind</code></td></tr><tr><td><code>{text: &quot;Question: ...&quot;}</code> with no <code>kind</code></td><td><code>question</code></td><td><code>no_kind</code></td></tr><tr><td><code>{text, parts?}</code> with no <code>kind</code> (guide)</td><td><code>draft</code>, or <code>question</code> for a <code>Question:</code> text</td><td><code>no_kind</code></td></tr><tr><td><code>{text, gaps}</code> with no <code>kind</code></td><td><code>critique</code></td><td><code>no_kind</code></td></tr><tr><td><code>{text, changed, open?}</code> with no <code>kind</code></td><td><code>revision</code></td><td><code>no_kind</code></td></tr><tr><td><code>{text, plan}</code> with no <code>kind</code></td><td><code>plan_tree</code></td><td><code>no_kind</code></td></tr><tr><td><code>{type: &quot;post&quot; | &quot;objection&quot; | &quot;agree&quot; | &quot;block&quot;, text, cite?}</code></td><td>the same word as the <code>kind</code></td><td><code>type</code></td></tr><tr><td><code>{step: &quot;plan&quot; | &quot;tool&quot; | &quot;check&quot; | &quot;ask&quot; | &quot;done&quot;, ...}</code></td><td>the same word as the <code>kind</code></td><td><code>step</code></td></tr><tr><td><code>{step: &quot;stop&quot;, ...}</code>, <code>{step: &quot;act&quot;, ...}</code>, <code>{&quot;text&quot;: ...}</code> in the loop</td><td><code>done</code>, <code>tool</code>, <code>done</code></td><td><code>stop</code>, <code>act</code>, <code>text</code></td></tr></tbody></table><p>A reply that has a <code>kind</code> is never treated as an old shape. A reply with a <code>kind</code> and the old key (<code>type</code> or <code>step</code>) is not valid for a loop step, and the old key is dropped for a room entry.</p><h3 id="the-legacy-shape-log-line" tabindex="-1">The <code>legacy_shape</code> log line <a class="header-anchor" href="#the-legacy-shape-log-line" aria-label="Permalink to &quot;The `legacy_shape` log line&quot;">​</a></h3><p>Each old shape that is read is logged as one line, once per run for each shape:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;legacy_shape&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;roleId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;builder&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;shape&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;no_kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>kind</code> is the kind of the first reply that used the shape. A run is one role run, one loop run, one hand-off, one room round, one lead plan, or one <code>sdd go</code> call.</p><ul><li>A role run, a loop run, a hand-off receiver and a network owner write the line to their own run log (<code>.sdd/role-runs/conversation/&lt;role&gt;/&lt;run&gt;.jsonl</code>).</li><li>A room round, a lead plan and <code>sdd go</code> have no run log. They write the line, with a <code>ts</code> time, to <code>.sdd/role-runs/legacy-shapes.jsonl</code>.</li></ul><p>Count the lines to see whether anything still sends an old shape:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;legacy_shape&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .sdd/role-runs/legacy-shapes.jsonl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .sdd/role-runs/conversation/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.jsonl</span></span></code></pre></div><h3 id="when-they-go" tabindex="-1">When they go <a class="header-anchor" href="#when-they-go" aria-label="Permalink to &quot;When they go&quot;">​</a></h3><p>The old shapes are read through the 0.25 release line. They are removed in the next minor release (0.26.0) or later, and only if the log shows no hits in the dogfood runs. The removal is its own commit. A plain one-line text reply in a room is not an old shape: it is still typed by the entry classifier.</p><h2 id="change-a-reply" tabindex="-1">Change a reply <a class="header-anchor" href="#change-a-reply" aria-label="Permalink to &quot;Change a reply&quot;">​</a></h2><ol><li>Change the zod schema. The prompt text is generated from it.</li><li>Keep the valid examples and the invalid example passing their own schema (<code>prompt-standard.test.ts</code> checks this).</li><li>If a kind is added, add it to this page. <code>reply-kinds.test.ts</code> fails when a kind that a prompt offers is missing here.</li><li>Regenerate the snapshots with <code>pnpm exec vitest run -u</code> in <code>packages/core</code>, and read the diff.</li></ol>',26)])])}const u=t(a,[["render",i]]);export{k as __pageData,u as default};
